package server

import "net/http"

func checkoutHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(checkoutHTML))
}

const checkoutHTML = `<!doctype html>
<html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Payment Sandbox</title><style>body{font:16px system-ui;max-width:600px;margin:40px auto;padding:20px}input,button,select{display:block;padding:10px;margin:8px 0;width:100%;box-sizing:border-box}pre{white-space:pre-wrap}button{cursor:pointer}</style>
<h1>Payment Sandbox</h1><p>Gunakan data dan dana simulasi saja.</p>
<form id="form"><label>Nama<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Nomor HP<input name="phone" type="tel" maxlength="32"></label><label>Deskripsi<input name="description" maxlength="255" value="Simulasi pembayaran"></label><label>Skenario<select id="scenario"><option value="catering">Andika Catering</option><option value="subscription">Langganan aplikasi KPI</option><option value="custom">Custom</option></select></label><div id="items"></div><button type="button" id="add">Tambah item</button><p>Total: <strong id="total"></strong></p><button>Buat order dan pembayaran</button></form>
<p><a id="pay" hidden target="_blank" rel="noopener noreferrer">Buka Midtrans Sandbox</a></p>
<label>Nomor order<input id="number"></label><button id="check">Cek status</button><pre id="output" role="status"></pre>
<details><summary>Refund simulator (operator lokal)</summary><p>Gunakan transaksi Sandbox yang sudah settlement. Refresh status dahulu. Nominal 0 berarti full refund.</p><label>Nominal refund IDR<input id="refundAmount" type="number" min="0" step="1" value="0"></label><label>Alasan refund<input id="refundReason" maxlength="255" value="Simulasi refund"></label><button id="refund">Ajukan refund</button><button id="history">Riwayat refund</button><pre id="refundOutput" role="status"></pre></details>
<script>
const form=document.querySelector('#form'), number=document.querySelector('#number'), output=document.querySelector('#output'), pay=document.querySelector('#pay');
let key=crypto.randomUUID(), payload='';
const items=document.querySelector('#items'), total=document.querySelector('#total');
function addItem(id='',name='',price=10000,quantity=1){const row=document.createElement('div');row.innerHTML='<label>ID item<input class="sku" required maxlength="50"></label><label>Nama item<input class="itemname" required maxlength="50"></label><label>Harga IDR<input class="price" type="number" min="1" max="100000000" required></label><label>Jumlah<input class="qty" type="number" min="1" max="10000" required></label><button type="button" class="remove">Hapus item</button>';row.querySelector('.sku').value=id;row.querySelector('.itemname').value=name;row.querySelector('.price').value=price;row.querySelector('.qty').value=quantity;row.querySelector('.remove').onclick=()=>{row.remove();sum()};row.oninput=sum;items.append(row);sum()}
function lines(){return Array.from(items.children,row=>({id:row.querySelector('.sku').value,name:row.querySelector('.itemname').value,price:Number(row.querySelector('.price').value),quantity:Number(row.querySelector('.qty').value)}))}
function sum(){const amount=lines().reduce((n,i)=>n+i.price*i.quantity,0);total.textContent=amount.toLocaleString('id-ID',{style:'currency',currency:'IDR'});return amount}
function scenario(){items.replaceChildren();if(document.querySelector('#scenario').value==='catering'){addItem('NASI','Nasi box',25000,4);addItem('SNACK','Snack box',15000,2)}else if(document.querySelector('#scenario').value==='subscription'){addItem('KPI-MONTH','Langganan aplikasi KPI',99000,1)}else{addItem('CUSTOM','Item simulasi',10000,1)}}
document.querySelector('#scenario').onchange=scenario;document.querySelector('#add').onclick=()=>addItem();scenario();
async function call(path, options){const res=await fetch('/api/v1'+path,options);const data=await res.json();if(!res.ok)throw Error(data.error?.message||res.status);return data}
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button:not([type]),button[type=submit]');button.disabled=true;pay.hidden=true;try{const f=new FormData(form), body=JSON.stringify({customer:{name:f.get('name'),email:f.get('email'),phone:f.get('phone')},amount:sum(),currency:'IDR',description:f.get('description'),items:lines()});if(payload&&payload!==body){key=crypto.randomUUID();number.value=''}payload=body;const order=await call('/orders',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body});number.value=order.orderNumber;const p=await call('/orders/'+encodeURIComponent(number.value)+'/payments',{method:'POST'});const u=new URL(p.redirectUrl);if(u.protocol!=='https:'||u.hostname!=='app.sandbox.midtrans.com')throw Error('Invalid checkout URL');pay.href=u.href;pay.hidden=false;output.textContent=labels[p.status]||p.status;}catch(e){output.textContent=e.message}finally{button.disabled=false}};
const labels={pending:'Menunggu pembayaran',authorize:'Pembayaran diotorisasi',capture:'Pembayaran berhasil',settlement:'Pembayaran berhasil',cancel:'Pembayaran dibatalkan',expire:'Pembayaran kedaluwarsa',deny:'Pembayaran ditolak',failure:'Pembayaran gagal',refund:'Dana dikembalikan',partial_refund:'Dana dikembalikan sebagian',chargeback:'Pembayaran disengketakan'};
document.querySelector('#check').onclick=async()=>{const button=document.querySelector('#check');button.disabled=true;pay.hidden=true;output.textContent='Memeriksa status ke Midtrans...';try{const p=await call('/orders/'+encodeURIComponent(number.value.trim())+'/payments/refresh',{method:'POST'});output.textContent=(labels[p.status]||p.status)+'\nNomor order: '+p.orderNumber;if(['cancel','expire','deny','failure'].includes(p.status)){output.textContent+='\nSilakan buat order baru jika ingin melanjutkan pembayaran.';key=crypto.randomUUID();payload='';}}catch(e){output.textContent='Status terbaru belum dapat dikonfirmasi. '+e.message}finally{button.disabled=false}};
const refundOutput=document.querySelector('#refundOutput');
document.querySelector('#refund').onclick=async()=>{const button=document.querySelector('#refund'), order=number.value.trim(), amount=Number(document.querySelector('#refundAmount').value), reason=document.querySelector('#refundReason').value.trim();if(!order||!Number.isSafeInteger(amount)||amount<0||!reason){refundOutput.textContent='Isi nomor order, nominal dan alasan yang valid.';return}if(!confirm(amount===0?'Ajukan full refund Sandbox?':'Ajukan refund Rp'+amount.toLocaleString('id-ID')+'?'))return;button.disabled=true;try{const result=await call('/orders/'+encodeURIComponent(order)+'/refunds',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount,reason})});refundOutput.textContent=JSON.stringify(result,null,2);await document.querySelector('#check').onclick()}catch(e){refundOutput.textContent=e.message}finally{button.disabled=false}};
document.querySelector('#history').onclick=async()=>{try{refundOutput.textContent=JSON.stringify(await call('/orders/'+encodeURIComponent(number.value.trim())+'/refunds'),null,2)}catch(e){refundOutput.textContent=e.message}};
</script></html>`
